settings:

    on
    {{xml .Line.Username}}
    {{xml .Line.AuthName}}
    {{xml .Line.Password}}
    {{xml .Server.Host}}:{{.Server.Port}}
    {{xml .Line.DisplayName}}
    {{xml .Line.AccountLabel}}
    {{.Server.Expiry}}
{{- /* Text messages (SIP MESSAGE, RFC 3428): Snom documents no key to switch instant messages on that we could cite, so none is written; the phone shows a MESSAGE it receives as it does by default. Unverified on hardware (lab item). */}}
{{- /* HD voice: codec_priority_list of identity 1 in order of preference (Snom Service Hub, codec_priority_list; D3xx/D7xx/D8xx): G.722, Opus (D7xx and D8xx), PCMU, PCMA, then telephone-event for DTMF. Another identity of a multi-line model has the same setting with its own idx. Unverified on hardware (verify). */}}
    g722,{{if .Codecs.Opus}}opus,{{end}}pcmu,pcma,telephone-event
{{- /* MWI (spec S-1): user_mailbox names the mailbox the phone ties MWI to and dials for voicemail (Snom Service Hub, user_mailbox, D-series); Snom documents no separate subscribe flag. Unverified on hardware (lab item 1). */}}
    {{xml (or .Line.VoicemailCode "*97")}}
{{- /* Call waiting (phone-feature-parity S-18): call_waiting per line is on (waiting tone), visual (no tone) or off; Hello writes on or off from the extension's flag. Key and values as in Snom's own settings reference and the Tancredi snom template. Unverified on hardware (verify, lab item 26). */}}
    {{if .Line.CallWaiting}}on{{else}}off{{end}}
    {{xml .Phone.AdminPassword}}
{{- /* Web UI password. admin_mode_password is the keypad/admin-mode PIN only. The D3xx/D7xx web UI is protected by http_user with http_pass (Snom Service Hub, http_user and http_pass); the D86x/D89x replace them with webserver_admin_password (Hub, since 10.1.115.0). The same per-phone password every other vendor gets (Phone.AdminPassword). */}}
    admin
    {{xml .Phone.AdminPassword}}
    {{xml .Phone.AdminPassword}}
{{- /* Call recording: the phone's Record key sends SIP INFO "Record: on" / "Record: off" (Hub, recording_mechanism = SIP, the default) which the PBX turns into the *1 recording toggle. */}}
    SIP
{{- /* Star codes (Hub, dnd_on_code and dnd_off_code; fwd_all, fwd_busy and fwd_time on/off codes, per identity, since 8.7.4): with a code set the phone's DND and forward keys dial the PBX's code (a forward code followed by the target) instead of acting alone. */}}
{{- with .Codes.DNDOn}}
    {{xml .}}
{{- end}}
{{- with .Codes.DNDOff}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardOn}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardOff}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardBusyOn}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardBusyOff}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardNoAnswerOn}}
    {{xml .}}
{{- end}}
{{- with .Codes.ForwardNoAnswerOff}}
    {{xml .}}
{{- end}}
    {{xml .Prov.URL}}{mac}
    on
    rel
    {{.Prov.ResyncSeconds}}
    {{xml .Time.NTP}}
{{- with .Time.TZ.SnomCode}}
    {{xml .}}
{{- end}}
{{- /* Paging and intercom (phonebooks-ptt P-12, P-13): answer an Alert-Info info=alert-autoanswer call by itself only when the phone is idle (Snom Service Hub, answer_after_policy: off, idle, always, not_busy; D series). Unverified on hardware (verify). */}}
    idle
{{- with .Book}}
    url {{xml .URL}}
{{- end}}
{{- with .Firmware}}
    auto_update
    {{xml .URL}}
{{- end}}

{{- /* Trusted CA (Hub, " tag"): inside , outside ; type="base64" carries the certificate itself (firmware 8.7.5.52 / 8.9.3.41 and later), available as soon as the line is read. */}}
{{- with .Prov.CACertBase64}}

    {{.}}

{{- end}}

{{- /* BLF keys are placed by Render (internal/prov/keycaps.go): fkey 0 is the account's line key, so BLF starts at idx 1, runs to the model's last key and on into expansion module 1 (UXM, 18 keys; Hub, "Function Key Index Ranges"); keys past that are dropped. Snom's BLF pickup is by key press with the Replaces header or a BroadWorks code, so no pickup value is written. */}}
{{- range $i, $k := .BLF}}
    blf {{xml $k.URI}}
{{- end}}
